import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final Pattern NUMERIC_CHECK = Pattern.compile("^[0-9]+$");
    private static final String[] BLOCKED_KEYWORDS = {"DROP", "ALTER", "TRUNCATE", "CREATE"};

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate report ID is numeric
        if (reportId == null || !NUMERIC_CHECK.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Validate direction parameter
        if (direction != null && !direction.equalsIgnoreCase("ASC") 
                && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Check for DDL keywords in sort parameter
        if (sortCol != null) {
            String upper = sortCol.toUpperCase();
            for (String kw : BLOCKED_KEYWORDS) {
                if (upper.contains(kw)) {
                    resp.sendError(400, "Invalid sort parameter");
                    return;
                }
            }
        }

        // Default sort column
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "created_at";
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getConnection();
            // Build query - reportId is validated numeric, direction is validated
            // sortCol has DDL keywords blocked
            String query = "SELECT id, title, amount, created_at FROM reports " +
                          "WHERE project_id = " + reportId + 
                          " ORDER BY " + sortCol + " " + direction;

            stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\":").append(rs.getInt("id"))
                   .append(",\"title\":\"").append(rs.getString("title"))
                   .append("\",\"amount\":").append(rs.getDouble("amount"))
                   .append(",\"created_at\":\"").append(rs.getString("created_at"))
                   .append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
